"Делим поровну: 39 570 : 6 = 6 595. Проверка: 6 595 · 6 = 39 570.": "On partage en parts égales : 39 570 : 6 = 6 595. Vérification : 6 595 · 6 = 39 570.",
"Измерения складывать нельзя. V = 3 · 4 · 2 = 24 дм³, а не 9 дм³.": "On ne peut pas additionner les dimensions. V = 3 · 4 · 2 = 24 dm³, et non 9 dm³.",
"При умножении на 100 справа приписываем два нуля. 2 · 100 = 200.": "Quand on multiplie par 100, on écrit deux zéros à droite. 2 · 100 = 200.",
"Например, в слое 5 · 3 = 15 кубиков, слоёв 4: 15 · 4 = 60 кубиков": "Par exemple, dans une couche il y a 5 · 3 = 15 cubes, il y a 4 couches : 15 · 4 = 60 cubes",
"Велосипедист едет 15 км каждый час. Сколько км он проедет за 3 ч?": "Un cycliste roule 15 km chaque heure. Combien de km parcourra-t-il en 3 h ?",
"Остаток меньше делителя, поэтому наибольший остаток 100 − 1 = 99.": "Le reste est plus petit que le diviseur, donc le plus grand reste est 100 − 1 = 99.",
"Подумай: лёгкое это или тяжёлое. Чем тяжелее, тем крупнее единица.": "Réfléchis : est-ce léger ou lourd ? Plus c'est lourd, plus l'unité est grande.",
"сочетательное свойство: результат не зависит от расстановки скобок": "propriété d'associativité : le résultat ne dépend pas de la place des parenthèses",
"Определять по последней цифре, делится ли число на 2, на 5 и на 10": "Savoir déterminer, grâce au dernier chiffre, si un nombre est divisible par 2, par 5 et par 10",
"двадцать шесть миллионов восемьсот девяносто тысяч девятьсот девять": "vingt-six millions huit cent quatre-vingt-dix mille neuf cent neuf",
"Это свойство помогает умножать устно: 12 · 3 = 10 · 3 + 2 · 3 = 36.": "Cette propriété aide à multiplier de tête : 12 · 3 = 10 · 3 + 2 · 3 = 36.",
"Идут в одну сторону, значит, скорости вычитаем: 80 − 60 = 20 м/мин.": "Ils vont dans le même sens, donc on soustrait les vitesses : 80 − 60 = 20 m/min.",
"Периметр квадрата со стороной 6 см равен 24 см, а площадь — 36 см².": "Le périmètre d'un carré de côté 6 cm est égal à 24 cm, et son aire à 36 cm².",
"Периметр квадрата со стороной 6 см равен 24 см, а площадь — 36 см².": "Le périmètre d'un carré de côté 6 cm est égal à 24 cm, et son aire à 36 cm².",
"Находить доли часа, суток, года и века и переводить единицы времени": "Trouver des fractions d'une heure, d'un jour, d'une année et d'un siècle et convertir les unités de temps",
"Если в числе нет единиц какого-то разряда, в этом разряде считают 0.": "S'il n'y a pas d'unités d'un certain rang dans un nombre, on compte 0 à ce rang.",
"Один билет в кино стоит 1 000 тенге. Сколько стоят 47 таких билетов?": "Un billet de cinéma coûte 1 000 tenge. Combien coûtent 47 billets comme celui-là ?",
"Один билет в кино стоит 1 000 тенге. Сколько стоят 47 таких билетов?": "Un billet de cinéma coûte 1 000 tenge. Combien coûtent 47 billets comme celui-là ?",
"Поезд идёт со скоростью 70 км/ч. За сколько часов он пройдёт 840 км?": "Un train roule à 70 km/h. En combien d'heures parcourra-t-il 840 km ?",
"Если единицу делаем крупнее, число делим. 6 000 см³ : 1 000 = 6 дм³.": "Si l'unité devient plus grande, on divise le nombre. 6 000 cm³ : 1 000 = 6 dm³.",
"Если единицу делаем крупнее, число делим. 6 000 см³ : 1 000 = 6 дм³.": "Si l'unité devient plus grande, on divise le nombre. 6 000 cm³ : 1 000 = 6 dm³.",
"По какой формуле находят расстояние, если известны скорость и время?": "Avec quelle formule trouve-t-on la distance quand on connaît la vitesse et le temps ?",
"В числе 4 300 только два нуля на конце. 4 300 : 1 000 = 4 (ост. 300).": "Dans le nombre 4 300, il n'y a que deux zéros à la fin. 4 300 : 1 000 = 4 (reste 300).",
"В числе 4 300 только два нуля на конце. 4 300 : 1 000 = 4 (ост. 300).": "Dans le nombre 4 300, il n'y a que deux zéros à la fin. 4 300 : 1 000 = 4 (reste 300).",
"49 143 − 8 530 = 40 613. Сравниваем 40 613 и 40 413: 40 613 > 40 413.": "49 143 − 8 530 = 40 613. On compare 40 613 et 40 413 : 40 613 > 40 413.",
"49 143 − 8 530 = 40 613. Сравниваем 40 613 и 40 413: 40 613 > 40 413.": "49 143 − 8 530 = 40 613. On compare 40 613 et 40 413 : 40 613 > 40 413.",
